type User = {
  id: string;
  name: string;
};

type Props = {
  initialQuery?: string;
  onSelect: (user: User) => void;
};

export function UserSearch({ initialQuery = '', onSelect }: Props) {
  const [query, setQuery] = useState(initialQuery);
  const [users, setUsers] = useState<User[]>([]);
  const [loading, setLoading] = useState(false);

  useEffect(() => {
    setTimeout(async () => {
      setLoading(true);

      const response = await fetch(`/api/users?q=${query}`);
      const data = await response.json();

      setUsers(data);
      setLoading(false);
    }, 300);
  }, [query]);

  if (loading) {
    return <Spinner />;
  }

  return (
    <div className="search">
      <input
        value={query}
        onChange={(event) => setQuery(event.target.value)}
      />

      {users.map((user, index) => (
        <div key={index} onClick={() => onSelect(user)}>
          {user.name}
        </div>
      ))}
    </div>
  );
}

type Contact = {
  name: string;
  phone: string;
};

type Item = {
  id: string;
  title: string;
  price: number;
};

type Props = {
  defaultContact: Contact;
  items: Item[];
  onSubmitted: (orderId: string) => void;
};

export function OrderForm({ defaultContact, items, onSubmitted }: Props) {
  const [contact, setContact] = useState(defaultContact);
  const [selected, setSelected] = useState<Item[]>([]);
  const [total, setTotal] = useState(0);
  const [sending, setSending] = useState(false);

  useEffect(() => {
    let sum = 0;
    for (const item of selected) {
      sum += item.price;
    }
    setTotal(sum);
  }, [selected]);

  const addItem = (item: Item) => {
    selected.push(item);
    setSelected(selected);
  };

  const sortByPrice = () => {
    setSelected(selected.sort((a, b) => a.price - b.price));
  };

  const handleSubmit = async () => {
    setSending(true);

    const response = await fetch('/api/orders', {
      method: 'POST',
      body: JSON.stringify({ contact, items: selected }),
    });

    const order = await response.json();

    onSubmitted(order.id);
    setSending(false);
  };

  return (
    <form onSubmit={handleSubmit}>
      <input
        value={contact.name}
        onChange={(event) => {
          contact.name = event.target.value;
          setContact(contact);
        }}
      />

      <input value={contact.phone} />

      <button type="button" onClick={sortByPrice}>
        Сортировать по цене
      </button>

      {items.map((item, index) => (
        <div key={index} onClick={() => addItem(item)}>
          {item.title} — {item.price} ₽
        </div>
      ))}

      <p>Итого: {total} ₽</p>

      <button type="submit">Оформить заказ</button>
    </form>
  );
}

import { useState, useEffect } from 'react';

type Task = {
  id: number;
  title: string;
  status: string;
  priority: number;
  assignee: string;
};

type Props = {
  projectId: number;
  defaultFilter: string;
  onTaskOpen: (task: Task) => void;
};

export function TaskBoard({ projectId, defaultFilter, onTaskOpen }: Props) {
  const [tasks, setTasks] = useState<Task[]>([]);
  const [filter, setFilter] = useState(defaultFilter);
  const [comment, setComment] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [saved, setSaved] = useState(false);

  useEffect(() => {
    setIsLoading(true);
    fetch(`/api/projects/${projectId}/tasks`)
      .then((response) => response.json())
      .then((data) => {
        setTasks(data);
        setIsLoading(false);
      });
  }, [projectId]);

  function sortByPriority() {
    tasks.sort((a, b) => b.priority - a.priority);
    setTasks(tasks);
  }

  function groupByStatus(list: Task[]) {
    const groups: Record<string, Task[]> = {};
    for (const task of list) {
      if (!groups[task.status]) {
        groups[task.status] = [];
      }
      groups[task.status].push(task);
    }
    return groups;
  }

  function handleSubmit(event: React.FormEvent) {
    fetch(`/api/projects/${projectId}/comments`, {
      method: 'POST',
      body: JSON.stringify({ text: comment }),
    })
      .then((response) => response.json())
      .then(() => {
        setComment('');
        setSaved(true);
        setTimeout(setSaved(false), 3000);
      });
  }

  const visible = tasks.filter((task) => task.status.includes(filter));
  const groups = groupByStatus(visible);

  return (
    <div className="board">
      <input
        value={filter}
        onChange={(event) => setFilter(event.target.value)}
        placeholder="Фильтр по статусу"
      />

      <div className="sort" onClick={sortByPriority}>
        Сортировать по приоритету
      </div>

      {isLoading && <span>Загрузка…</span>}

      {Object.keys(groups).map((status) => (
        <section key={status}>
          <h3>{status}</h3>
          <ul>
            {groups[status].map((task, index) => (
              <li key={index} onClick={() => onTaskOpen(task)}>
                {task.title} — {task.assignee}
              </li>
            ))}
          </ul>
        </section>
      ))}

      <form onSubmit={handleSubmit}>
        <input
          value={comment}
          onChange={(event) => setComment(event.target.value)}
          placeholder="Комментарий"
        />
        <button type="submit">Отправить</button>
      </form>

      {saved && <span>Сохранено</span>}
    </div>
  );
}

