import { useEffect, useState } from 'react';

type User = { id: string; name: string };

type State =
  | { kind: 'idle' }
  | { kind: 'loading' }
  | { kind: 'error'; message: string }
  | { kind: 'empty' }
  | { kind: 'success'; users: User[] };

type Props = { onSelect: (user: User) => void };

export function Autocomplete({ onSelect }: Props) {
  const [query, setQuery] = useState('');
  const [state, setState] = useState<State>({ kind: 'idle' });

  useEffect(() => {
    const text = query.trim();
    if (!text) {
      setState({ kind: 'idle' });
      return;
    }

    const controller = new AbortController();
    const timerId = setTimeout(async () => {
      setState({ kind: 'loading' });
      try {
        const response = await fetch(`/api/users?q=${encodeURIComponent(text)}`, {
          signal: controller.signal,
        });
        if (!response.ok) throw new Error(`Сервер ответил ${response.status}`);
        const users: User[] = await response.json();
        setState(users.length > 0 ? { kind: 'success', users } : { kind: 'empty' });
      } catch (error) {
        if ((error as Error).name === 'AbortError') return; // отмену мы устроили сами
        setState({ kind: 'error', message: 'Не удалось загрузить' });
      }
    }, 300);

    return () => {
      clearTimeout(timerId);
      controller.abort();
    };
  }, [query]);

  return (
    <div>
      <input
        value={query}
        onChange={(event) => setQuery(event.target.value)}
        aria-label="Поиск пользователей"
      />
      {state.kind === 'loading' && <p>Загрузка…</p>}
      {state.kind === 'error' && <p role="alert">{state.message}</p>}
      {state.kind === 'empty' && <p>Ничего не нашлось</p>}
      {state.kind === 'success' && (
        <ul>
          {state.users.map((user) => (
            <li key={user.id}>
              <button type="button" onClick={() => onSelect(user)}>
                {user.name}
              </button>
            </li>
          ))}
        </ul>
      )}
    </div>
  );
}

