// Эталон useFetch. Задача с реального собеседования, ~10 минут лайв-кодинга.
// Требования: url + options; возврат { data, error, loading, refetch };
// гонки запросов; отмена при размонтировании; response.ok как ошибка;
// отсутствие setState после размонтирования.

import { useCallback, useEffect, useRef, useState } from 'react';

export interface UseFetchOptions {
  method?: string;
  headers?: Record<string, string>;
  body?: BodyInit | null;
}

export interface UseFetchResult<T> {
  data: T | null;
  error: Error | null;
  loading: boolean;
  refetch: () => void;
}

export function useFetch<T>(url: string, options?: UseFetchOptions): UseFetchResult<T> {
  const [data, setData] = useState<T | null>(null);
  const [error, setError] = useState<Error | null>(null);
  const [loading, setLoading] = useState<boolean>(false);

  // options приходит из вызывающего кода и почти всегда создаётся объектным
  // литералом прямо в JSX. Такой объект НОВЫЙ на каждом рендере, и если
  // положить его в зависимости эффекта — эффект будет перезапускаться
  // бесконечно. Поэтому держим последнее значение в ref: оно доступно внутри
  // эффекта, но не участвует в сравнении зависимостей.
  const optionsRef = useRef<UseFetchOptions | undefined>(options);
  optionsRef.current = options;

  // Номер запроса. Каждый новый запрос увеличивает счётчик и запоминает свой
  // номер. Перед записью в состояние сравниваем: если номер устарел — значит
  // за это время стартовал более свежий запрос, и результат старого не нужен.
  const requestIdRef = useRef<number>(0);

  // Флаг «компонент ещё на экране». Нужен для требования «не вызывать setState
  // после размонтирования»: промис может завершиться уже после того, как
  // компонент убран из дерева.
  const isMountedRef = useRef<boolean>(true);

  // Счётчик ручных перезапросов. Менять состояние — самый простой способ
  // заставить эффект выполниться заново: число попадает в зависимости.
  const [attempt, setAttempt] = useState<number>(0);

  // useCallback нужен, чтобы refetch не менялся между рендерами. Иначе
  // вызывающий компонент, положивший refetch в зависимости своего эффекта,
  // получит бесконечный цикл.
  const refetch = useCallback(() => {
    setAttempt((n) => n + 1);
  }, []);

  // Отдельный эффект с пустыми зависимостями: выставляет флаг при монтировании
  // и снимает при размонтировании. В StrictMode эффекты вызываются дважды,
  // поэтому флаг обязательно поднимается в теле, а не только объявляется.
  useEffect(() => {
    isMountedRef.current = true;
    return () => {
      isMountedRef.current = false;
    };
  }, []);

  useEffect(() => {
    // Свой контроллер на каждый запрос. Один контроллер нельзя переиспользовать:
    // после abort() его signal навсегда остаётся прерванным.
    const controller = new AbortController();

    // Инкремент и запоминание своего номера ДО старта запроса.
    const myRequestId = requestIdRef.current + 1;
    requestIdRef.current = myRequestId;

    // Проверка «этот ответ ещё актуален». Два условия: компонент на экране
    // и с момента старта не было более нового запроса.
    const isCurrent = () => isMountedRef.current && myRequestId === requestIdRef.current;

    setLoading(true);
    setError(null);

    const currentOptions = optionsRef.current;

    fetch(url, {
      method: currentOptions?.method ?? 'GET',
      headers: currentOptions?.headers,
      body: currentOptions?.body ?? null,
      signal: controller.signal,
    })
      .then(async (response) => {
        // fetch НЕ отклоняется на 404 и 500 — он отклоняется только при сетевом
        // сбое. Статус надо проверять руками, иначе код пойдёт парсить
        // страницу ошибки как JSON.
        if (!response.ok) {
          throw new Error(`HTTP ${response.status} ${response.statusText}`);
        }
        return (await response.json()) as T;
      })
      .then((json) => {
        if (!isCurrent()) return;
        setData(json);
        setError(null);
      })
      .catch((cause: unknown) => {
        // Отмена — не ошибка приложения. Прерванный запрос отклоняется
        // с DOMException по имени AbortError, и показывать это пользователю
        // не нужно: мы сами его отменили.
        if (cause instanceof DOMException && cause.name === 'AbortError') return;
        if (!isCurrent()) return;
        setError(cause instanceof Error ? cause : new Error(String(cause)));
        setData(null);
      })
      .finally(() => {
        // loading снимается только для актуального запроса. Иначе устаревший
        // ответ погасил бы индикатор у нового, ещё идущего.
        if (!isCurrent()) return;
        setLoading(false);
      });

    // Очистка выполняется и при размонтировании, и ПЕРЕД каждым следующим
    // запуском эффекта — то есть при смене url. Отмена здесь закрывает
    // сразу два требования: гонки и отсутствие работы после размонтирования.
    return () => {
      controller.abort();
    };
  }, [url, attempt]);

  return { data, error, loading, refetch };
}
